import{_ as l,o as r,c as e,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-09-14","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-09-14","date":"2020-09-14T00:00:00.000Z","updated":"2020-09-15T00:00:00.000Z","tags":["Ceph","Distributed Storage","Orchestrator","Pull Request","Documentation"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-09-14.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-09-14.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-09-14.md"};function a(s,t,n,h,u,g){return r(),e("div",null,[...t[0]||(t[0]=[i('<p>会议纪要</p><h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><ul><li><strong>会议主题</strong>: Ceph Orchestrator协调器会议</li><li><strong>参会人员</strong>: 核心团队成员</li><li><strong>会议时间</strong>: 2020年9月14日</li></ul><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>新拉取请求（Pull Request）讨论</strong></p><ul><li><strong>提出者</strong>: Paul</li><li><strong>内容</strong>: 引入adm daemon在所有主机上的持久性，编号为130130。</li><li><strong>目的</strong>: 提升协调器和仪表板的性能，解决从主机获取信息所需时间过长的问题。</li><li><strong>讨论</strong>: <ul><li>该请求旨在收集主机上的硬件信息，未来可能扩展为更全面的fadm diamond功能。</li><li>讨论了设计架构和性能问题，特别是SSH连接的效率和持久性问题。</li></ul></li></ul></li><li><p><strong>文档站点问题</strong></p><ul><li><strong>提出者</strong>: Zach</li><li><strong>内容</strong>: 当前有两个不同的文档站点，一个在readthedocs.io，另一个在docs.conf。</li><li><strong>问题</strong>: <ul><li>docs.conf的搜索功能有限，只能搜索第一个字符串。</li><li>readthedocs.io提供了更好的搜索功能，但没有API文档的自动生成。</li></ul></li><li><strong>讨论</strong>: <ul><li>需要找到一个解决方案，既能提供良好的搜索功能，又能自动生成API文档。</li><li>提出了将API文档源代码提交到源代码树的建议，但存在维护成本问题。</li></ul></li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li><strong>新拉取请求</strong>: 继续讨论和优化，确保其设计符合当前需求，同时考虑未来的扩展性。</li><li><strong>文档站点</strong>: 需要进一步讨论和寻找解决方案，以整合搜索功能和API文档生成。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li><strong>新拉取请求</strong>: <ul><li>继续与Paul合作，优化请求内容。</li><li>设计高层次的工作流程文档，明确需求和接口。</li></ul></li><li><strong>文档站点</strong>: <ul><li>在领导团队会议上进一步讨论。</li><li>探索更有效的解决方案，以改善文档站点的搜索和API文档生成功能。</li></ul></li></ul><h3 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h3><ul><li><strong>性能和可扩展性</strong>: 讨论了cephadm和仪表板的性能问题，特别是SSH连接的管理和优化。</li><li><strong>设计文档</strong>: 强调了设计文档的重要性，以确保项目的长期维护和改进。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li><strong>下次会议</strong>: 下次同步会议再见。</li></ul>',13)])])}const _=l(o,[["render",a]]);export{c as __pageData,_ as default};
